	height:3em;
	border:solid 2px rgb(245,245,245);
	background-color:#CCF;
	text-align:inherit;
	color:rgb(80,80,80);
	font-weight:bold;
	font-size:100% !important;
	font-size:90%;
}
.ancalc td {
	border:solid 2px rgb(245,245,245);
	background-color:#FFF;
	text-align:left;
}
.ancalc input.output {
	border:solid 0px rgb(245,245,245);
	background-color:#FFF;
}
