<div class ="ancalc">

  <form id="formc" name="formc" action="" method="post">
    <table width="447" border="0" cellpadding="2" cellspacing="0">
      <tbody>
        <tr>
          <th class="top" colspan="6">محاسبه وزن ایده آل بدن برای بزرگسالان </th>
        </tr>
        <tr>
          <th colspan="6">لطفا موارد زیر را وارد نمایید</th>
        </tr>
        <tr>
          <td width="117">جنسیت شما</td>
          <td colspan="5"><select id="select"  tabindex="1" 
      onchange="recalc_onclick('p1B2')" size="1" name="p1B2">
              <option value="Male">مرد</option>
              <option value="Female" selected="selected">زن</option>
            </select></td>
        </tr>
        <tr>
          <td>قد شما</td>
          <td colspan="5"><input id="p1B32" 
      onblur="this.value=eedisplayFloat(eeparseFloat(this.value));recalc_onclick('p1B3')" 
       tabindex="2" size="3"  name="p1B3" />
            <select id="select2"  tabindex="3" 
      onchange="recalc_onclick('p1C3')" size="1" name="p1C3">
              <option 
        value="centimeters" selected="selected">سانتیمتر</option>
              <option 
        value="inches">اینچ</option>
            </select></td>
        </tr>
        <tr>
          <td>قالب بدن شما</td>
          <td colspan="5"><select id="select3"  tabindex="4" 
      onchange="recalc_onclick('p1B4')" size="1" name="p1B4">
              <option 
        value="light">لاغر</option>
              <option value="medium" selected="selected">متوسط</option>
              <option 
        value="heavy">درشت</option>
            </select></td>
        </tr>
        <tr>
          <th colspan="6">جواب</th>
        </tr>
        <tr>
          <td>&nbsp;</td>
          <td width="152">وزن ایده آل بدن شما به کیلوگرم </td>
          <td width="166" colspan="4">وزن ایده آل بدن شما به پوند</td>
        </tr>
        <tr>
          <td>میانگین</td>
          <td>
              <input name="p1B6" type="text" id="p1B62" size="17" readonly="readonly" style="text-align: center" />
            </td>
          <td colspan="4">
              <input id="p1B112" 
       
      readonly="readonly" size="17" name="p1B11" style="text-align: center" />
            </td>
        </tr>
        <tr>
          <td>رنج</td>
          <td>
              <input id="p1D63" 
       
      readonly="readonly" size="4" name="p1D6" style="text-align: center" />
              تا
              <input id="p1E63" 
       
      readonly="readonly" size="4" name="p1E6" style="text-align: center" />
            </td>
          <td colspan="4">
              <input id="p1D112" 
       
      readonly="readonly" size="4" name="p1D11" style="text-align: center" />
              تا
              <input id="p1E112" 
       
      readonly="readonly" size="4" name="p1E11" style="text-align: center" />
            </td>
        </tr>
        <tr>
          <td colspan="6"><input type="checkbox" checked="checked" name="automatic_recalc" value="ON" />

محاسبه خودکار&nbsp;
<input onclick="recalc_onclick('')" type="button" value="محاسبه دوباره" name="do_recalc" /></td>
        </tr>
        <tr>
